={{ (() => {
  const escapar = (v) => "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'";
  const numero = (v) => (v === null || v === undefined) ? 'NULL' : Number(v);
  const idObra = numero($json.id_obra);
  const ocsJson = escapar(JSON.stringify($json.ocs || []));
  const resumoJson = $json.resumo == null ? 'NULL' : "CAST(" + escapar(JSON.stringify($json.resumo)) + " AS JSON)";
  return "INSERT INTO oc_orcamentos (id_obra, total, ocs, resumo) " +
    "SELECT " + idObra + ", " + numero($json.total) + ", CAST(" + ocsJson + " AS JSON), " + resumoJson + " " +
    "FROM DUAL WHERE EXISTS (SELECT 1 FROM obras WHERE id = " + idObra + ") " +
    "ON DUPLICATE KEY UPDATE total = VALUES(total), ocs = VALUES(ocs), resumo = VALUES(resumo)";
})() }}
